angular.module('angular-highlight', []).directive('highlight', () => ({
    link(h, i, e) {
        e.highlightClass || (e.highlightClass = 'angular-highlight');
        const g = function (h, i) {
            return `<a href="/?q=${h}" class="${e.highlightClass}">${h}</a>`;
        };
        const l = function (h) {
            let i;
            const e = (h = h.replace(new RegExp(',$', 'g'), '').split(',')).length;
            for (i = 0; i < e; i++) h[i] = h[i].replace(new RegExp('^ | $', 'g'), '');
            return h;
        };
        h.$watch('keywords', () => {
            if (!h.keywords || h.keywords == '') return (i.html(h.highlight), !1);
            const e = l(h.keywords);
            const r = new RegExp(e.join('|'), 'gmi');
            const t = h.highlight.replace(r, g);
            i.html(t);
        });
    },
    replace: !1,
    scope: { highlight: '=', keywords: '=' },
}));
